<?php
namespace Modules\Finance\Models;use Illuminate\Database\Eloquent\Model;use LogicException;use Modules\Core\Models\Concerns\BelongsToCompany;class PeriodCloseRun extends Model{use BelongsToCompany;protected $fillable=['company_id','period','status','checklist_snapshot','attestations','snapshot_hash','prepared_by','prepared_at','approved_by','approved_at','closed_by','closed_at'];protected function casts():array{return['checklist_snapshot'=>'array','attestations'=>'array','prepared_at'=>'datetime','approved_at'=>'datetime','closed_at'=>'datetime'];}protected static function booted():void{static::updating(function(self$r){if(in_array($r->getOriginal('status'),['APPROVED','CLOSED'],true)&&$r->isDirty(['company_id','period','checklist_snapshot','attestations','snapshot_hash','prepared_by','prepared_at']))throw new LogicException('Approved period-close snapshot bersifat immutable.');});static::deleting(fn()=>throw new LogicException('Period-close run bersifat append-only.'));}}
